function openTaskStore(filename) {
  // Never initialize or migrate a pre-existing database. Inspect read-only first.
  if (existsSync(filename)) {
    const fd = openSync(filename, 'r'); const header = Buffer.alloc(16);
    try { readSync(fd, header, 0, 16, 0); } finally { closeSync(fd); }
    if (header.toString() !== 'SQLite format 3\0') throw new Error('Invalid persistence.');
    const check = new DatabaseSync(filename, { readOnly: true });
    try {
      if (check.prepare('PRAGMA quick_check').get().quick_check !== 'ok' || check.prepare('PRAGMA user_version').get().user_version !== 1)
        throw new Error('Invalid persistence.');
      const columns = check.prepare('PRAGMA table_info(tasks)').all().map(x => x.name);
      if (columns.join(',') !== 'id,title,description,label,status,revision,createdAt,updatedAt') throw new Error('Invalid persistence.');
      for (const row of check.prepare('SELECT * FROM tasks').all()) {
        validateTask({ title: row.title, description: row.description, label: row.label, status: row.status, revision: row.revision }, true);
        if (!/^[0-9a-f-]{36}$/.test(row.id) || !Number.isFinite(Date.parse(row.createdAt)) || !Number.isFinite(Date.parse(row.updatedAt))) throw new Error('Invalid persistence.');
      }
    } finally { check.close(); }
  }
  const fresh = !existsSync(filename);
  const db = new DatabaseSync(filename);
  try { if (fresh) db.exec(schema); db.exec('PRAGMA busy_timeout = 2000;'); }
  catch (e) { db.close(); throw e; }
  const get = id => db.prepare('SELECT * FROM tasks WHERE id = ?').get(id);
  return {
    list: () => db.prepare('SELECT * FROM tasks ORDER BY createdAt, id').all(),
    get,
    create(body) {
      const t = validateTask(body); const id = randomUUID(); const now = new Date().toISOString();
      db.prepare('INSERT INTO tasks VALUES (?,?,?,?,?,1,?,?)').run(id, t.title, t.description, t.label, t.status, now, now);
      return get(id);
    },
    update(id, body) {
      const t = validateTask(body, true);
      const result = db.prepare('UPDATE tasks SET title=?, description=?, label=?, status=?, revision=revision+1, updatedAt=? WHERE id=? AND revision=?')
        .run(t.title, t.description, t.label, t.status, new Date().toISOString(), id, t.revision);
      if (!result.changes) throw new TaskError(get(id) ? 409 : 404, get(id) ? 'Task changed. Reload current task before editing.' : 'Task not found.');
      return get(id);
    },
    close: () => db.close()
  };
}

function validateTask(body, editing = false) {
  if (!body || typeof body !== 'object' || Array.isArray(body) ||
      Object.keys(body).some(k => !keys.includes(k))) throw new TaskError(400, 'Invalid task fields.');
  if (typeof body.title !== 'string' || !body.title.trim() || body.title.length > 160 || /[\u0000-\u001f]/u.test(body.title))
    throw new TaskError(400, 'Title must be 1–160 characters without control characters.');
  const description = body.description === undefined ? '' : body.description;
  const label = body.label === undefined ? '' : body.label;
  const status = body.status === undefined ? 'open' : body.status;
  if (typeof description !== 'string' || description.length > 4000 || description.includes('\0'))
    throw new TaskError(400, 'Description must be at most 4000 characters.');
  if (typeof label !== 'string' || label.length > 80 || /[\u0000-\u001f]/u.test(label))
    throw new TaskError(400, 'Label must be at most 80 characters without control characters.');
  if (!['open', 'done'].includes(status)) throw new TaskError(400, 'Status must be open or done.');
  if (editing ? !Number.isSafeInteger(body.revision) || body.revision < 1 : body.revision !== undefined)
    throw new TaskError(400, 'A valid current revision is required for edits only.');
  return { title: body.title.trim(), description, label: label.trim(), status, revision: body.revision };
}

function createConnectionReader({config={},inferenceReader,fetchImpl=fetch}={}) {
  // Copy only fixed server-owned config fields; unknown fields never become URLs.
  const settings=Object.fromEntries(SERVICE_MAP.map(s=> {
    const c=config[s.id];
    return [s.id,c===undefined ? undefined : {enabled:c?.enabled===true,source:c?.source,fixturePort:c?.fixturePort,timeoutMs:c?.timeoutMs}];
  }));
  return async()=> {
    const observedAt=new Date().toISOString();
    const services=await Promise.all(SERVICE_MAP.map(async service=> {
      const c=settings[service.id];
      const base={id:service.id,label:service.label,status:'not_configured',source:'none',observedAt,elapsedMs:0,errors:[]};
      if(service.id==='inference') {
        const started=performance.now();
        try {
          const snapshot=await inferenceReader();
          return {...base,status:snapshot.status,source:snapshot.status === 'not_configured' ? 'none' : 'fixed_local_module',observedAt:snapshot.observedAt,elapsedMs:Math.round(performance.now()-started),errors:snapshot.errors.map(e=>({code:e.code}))};
        } catch {return {...base,status:'unavailable',errors:[{code:'observation_unavailable'}]};}
      }
      if(c===undefined) return base;
      if(!c.enabled) return {...base,status:'disabled'};
      if(service.id==='relay' && c.source==='disposable_fixture') {
        const r=await readDisposableHealth({port:c.fixturePort,timeoutMs:c.timeoutMs,fetchImpl});
        return {...base,status:r.status,source:'disposable_fixture',elapsedMs:r.elapsedMs,errors:r.error ? [{code:r.error}] : []};
      }
      return {...base,status:'unsupported',errors:[{code:service.id==='relay' ? 'source_route_held' : 'adapter_absent'}]};
    }));
    return {schemaVersion:'mesh-service-connections/v1',observedAt,services};
  };
}

async function startApp({ port = 0, dataDir = 'test/local-board', registryPath, activitySource = 'local_registry', serviceConfig = {}, inferenceConfig, inferenceTestReader } = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535 || [8787, 5173].includes(port)) throw new Error('Invalid port.');
  if (!['local_registry', 'disposable_fixture', 'frozen_manager_projection'].includes(activitySource)) throw new Error('Invalid activity source label.');
  if (registryPath && (typeof registryPath !== 'string' || /^[a-z][a-z0-9+.-]*:\/\//i.test(registryPath))) throw new Error('Invalid local registry path.');
  if (inferenceTestReader !== undefined && typeof inferenceTestReader !== 'function') throw new Error('Invalid test observation reader.');
  const fixedInferenceConfig = inferenceConfig === undefined ? undefined : structuredClone(inferenceConfig);
  const directory = await confinedPath(dataDir);
  const filename = await confinedPath(path.join(directory, 'tasks.sqlite'));
  const configuredRegistry = registryPath ? await confinedPath(registryPath) : undefined;
  await mkdir(directory, { recursive: true });
  let store;
  try { store = openTaskStore(filename); } catch { /* Preserve invalid data; serve a visible failure. */ }
  // Server-only test seam; CLI and HTTP never accept a reader or module path.
  // Validate again at the HTTP seam, including deliberately hostile test readers.
  const inference = async () => {
    const nowIso = new Date().toISOString();
    try {
      const value = inferenceTestReader ? await inferenceTestReader({config:fixedInferenceConfig,nowIso}) : await readFixedInference({ modulePath: path.join(ROOT, 'lib/inference-observation.mjs'), confine: confinedPath, config: fixedInferenceConfig, nowIso });
      return normalizeInference(value,nowIso);
    } catch { return normalizeInference({schemaVersion:'mesh-inference-observation/v1',observedAt:nowIso,status:'unavailable',nodes:[],errors:[]},nowIso); }
  };
  const connections = createConnectionReader({ config: serviceConfig, inferenceReader: inference });
  const server = http.createServer(async (req, res) => {
    const send = (code, body, type = 'application/json') => {
      res.writeHead(code, { 'Content-Type': `${type}; charset=utf-8`, 'Cache-Control': 'no-store',
        'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'no-referrer',
        'Content-Security-Policy': "default-src 'self'; connect-src 'self'; script-src 'self'; style-src 'self'; img-src 'none'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'" });
      res.end(type === 'application/json' ? JSON.stringify(body) : body);
    };
    try {
      const origin = `http://127.0.0.1:${server.address().port}`;
      if (req.headers.host !== `127.0.0.1:${server.address().port}`) throw new TaskError(403, 'Host is not allowed.');
      if (!['GET', 'HEAD'].includes(req.method) && (req.headers.origin !== origin || (req.headers['sec-fetch-site'] && req.headers['sec-fetch-site'] !== 'same-origin')))
        throw new TaskError(403, 'Same-origin writes are required.');
      const route = req.url;
      if (req.method === 'GET' && staticFiles.has(route)) {
        const [file, type] = staticFiles.get(route); return send(200, await readFile(path.join(ROOT, file)), type);
      }
      if (route === '/api/health' && req.method === 'GET') return send(store ? 200 : 503, {
        state: store ? 'ok' : 'unavailable', persistence: store ? 'sqlite' : 'unavailable', scope: 'local_trial',
        url: origin, integrations: 'not_connected',
        activity: { adapter: await adapterStatus(), registry: configuredRegistry ? 'configured' : 'not_configured', source: configuredRegistry ? activitySource : 'none' }
      });
      if (route === '/api/worker-activity' && req.method === 'GET') return send(200, await activity(configuredRegistry));
      if (route === '/api/service-connections' && req.method === 'GET') return send(200, await connections());
      if (route === '/api/inference-observation' && req.method === 'GET') return send(200, await inference());
      const taskRoute = /^\/api\/tasks(?:\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}))?$/.exec(route);
      if (!taskRoute) throw new TaskError(404, 'Route not found.');
      if (!store) throw new TaskError(503, 'Persistence unavailable. Existing data has been preserved.');
      const id = taskRoute[1];
      if (req.method === 'GET') {
        if (!id) return send(200, { tasks: store.list() });
        const task = store.get(id); if (!task) throw new TaskError(404, 'Task not found.');
        return send(200, { task });
      }
      if (req.method === 'POST' && !id) return send(201, { task: store.create(await jsonBody(req)) });
      if (req.method === 'PATCH' && id) return send(200, { task: store.update(id, await jsonBody(req)) });
      throw new TaskError(405, 'Method not allowed.');
    } catch (e) {
      if (!res.headersSent) send(e instanceof TaskError ? e.status : 503, { error: e instanceof TaskError ? e.message : 'Local operation unavailable. Data has not been reset.' });
    }
  });
  server.requestTimeout = 10000;
  server.headersTimeout = 10000;
  try { await new Promise((resolve, reject) => { server.once('error', reject); server.listen(port, '127.0.0.1', resolve); }); }
  catch (e) { store?.close(); throw e; }
  return { server, url: `http://127.0.0.1:${server.address().port}`, close: async () => {
    await new Promise((resolve, reject) => server.close(e => e ? reject(e) : resolve())); store?.close();
  } };
}

async function api(route, options = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 2500);
  try {
    const response = await fetch(route, { ...options, signal: controller.signal, cache: 'no-store', headers: { 'Content-Type': 'application/json' } });
    const raw = await response.text();
    if (raw.length > 262144) throw new Error('Response too large.');
    let body; try { body = JSON.parse(raw); } catch { throw new Error('Local app returned an invalid response.'); }
    if (!response.ok) throw new Error(typeof body?.error === 'string' ? body.error : 'Local app unavailable.');
    return body;
  } catch (e) {
    if (e.name === 'AbortError' || e instanceof TypeError) throw new Error('Local app unreachable or observation timed out. Refresh to retry.');
    throw e;
  } finally { clearTimeout(timer); }
}
